// Weekly Strategy Review
const portfolio = $('Get Portfolio').first().json;
const trades = $('Get All Trades').first().json;
const ticker = $('Get BTC Price').first().json;

const now = new Date();
const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).getTime() / 1000;
const currentPrice = ticker.tickers?.XXBTZUSD?.price || 0;

// Filter this week's trades
const allTrades = trades.trades || [];
const weekTrades = allTrades.filter(t => t.time >= weekAgo);

// Calculate weekly metrics
let weekBuys = 0, weekSells = 0;
let weekBuyCost = 0, weekSellRevenue = 0;
let weekFees = 0;
let weekBtcBought = 0, weekBtcSold = 0;

for (const trade of weekTrades) {
  const volume = parseFloat(trade.volume);
  const cost = parseFloat(trade.cost);
  weekFees += parseFloat(trade.fee);

  if (trade.side === 'buy') {
    weekBuys++;
    weekBuyCost += cost;
    weekBtcBought += volume;
  } else {
    weekSells++;
    weekSellRevenue += cost;
    weekBtcSold += volume;
  }
}

// All-time metrics for comparison
let totalBtcBought = 0, totalBuyCost = 0;
for (const trade of allTrades) {
  if (trade.side === 'buy') {
    totalBtcBought += parseFloat(trade.volume);
    totalBuyCost += parseFloat(trade.cost);
  }
}
const avgCostBasis = totalBtcBought > 0 ? totalBuyCost / totalBtcBought : currentPrice;

// Portfolio state
const equity = portfolio.portfolio?.equity || 0;
const totalValue = portfolio.portfolio?.total_value_usd || 0;

// Benchmark comparisons (simple)
// 1. HODL benchmark: What if we just held BTC from start?
// 2. USD benchmark: What if we just held USD?
const initialCapital = 50; // Starting capital
const btcHoldingsValue = totalBtcBought * currentPrice;
const actualReturn = ((equity - initialCapital) / initialCapital) * 100;

// Strategy effectiveness
let strategyGrade = 'C';
let strategyNotes = [];

if (actualReturn > 5) {
  strategyGrade = 'A';
  strategyNotes.push('Excellent: >5% return');
} else if (actualReturn > 0) {
  strategyGrade = 'B';
  strategyNotes.push('Good: Positive return');
} else if (actualReturn > -5) {
  strategyGrade = 'C';
  strategyNotes.push('Acceptable: Small loss, within risk tolerance');
} else {
  strategyGrade = 'D';
  strategyNotes.push('Review needed: Significant losses');
}

if (weekTrades.length === 0) {
  strategyNotes.push('No trades this week - consider if opportunities were missed');
}

if (weekBuys > 5) {
  strategyNotes.push('High trade frequency - ensure each trade has clear rationale');
}

// Recommendations for next week
let recommendations = [];
if (currentPrice < avgCostBasis * 0.95) {
  recommendations.push('Price below cost basis - good accumulation opportunity if confident');
}
if (currentPrice > avgCostBasis * 1.10) {
  recommendations.push('Price >10% above cost basis - consider partial profit taking');
}
if (weekFees > 0.50) {
  recommendations.push('Fees eating into returns - consider larger, less frequent trades');
}
if (recommendations.length === 0) {
  recommendations.push('Continue current strategy - no major adjustments needed');
}

const review = {
  week_ending: now.toISOString().split('T')[0],
  timestamp: now.toISOString(),

  this_week: {
    trades: weekTrades.length,
    buys: weekBuys,
    sells: weekSells,
    btc_bought: weekBtcBought,
    btc_sold: weekBtcSold,
    net_btc: weekBtcBought - weekBtcSold,
    cost_usd: weekBuyCost,
    revenue_usd: weekSellRevenue,
    fees_paid: weekFees
  },

  portfolio_state: {
    equity: equity,
    total_value_usd: totalValue,
    btc_price: currentPrice,
    avg_cost_basis: avgCostBasis,
    return_pct: actualReturn
  },

  benchmarks: {
    initial_capital: initialCapital,
    current_equity: equity,
    return_vs_hodl_usd: 'N/A (need historical price)',
    strategy_return_pct: actualReturn
  },

  assessment: {
    grade: strategyGrade,
    notes: strategyNotes,
    recommendations: recommendations
  },

  // For 50/50 split tracking
  reinvestment_ready: equity > initialCapital * 1.10,
  profit_available: Math.max(0, equity - initialCapital)
};

return [{ json: review }];

