console.log('THIS WEEK\'S ACTIVITY');
console.log('  Total Trades: ' + r.this_week.trades);
console.log('  Buys: ' + r.this_week.buys + ' | Sells: ' + r.this_week.sells);
console.log('  Net BTC: ' + r.this_week.net_btc.toFixed(8));
console.log('  Fees Paid: $' + r.this_week.fees_paid.toFixed(4));
console.log('');
console.log('PORTFOLIO STATE');
console.log('  Equity: $' + r.portfolio_state.equity.toFixed(2));
console.log('  BTC Price: $' + r.portfolio_state.btc_price.toFixed(2));
console.log('  Avg Cost Basis: $' + r.portfolio_state.avg_cost_basis.toFixed(2));
console.log('  Return: ' + r.portfolio_state.return_pct.toFixed(2) + '%');
console.log('');
console.log('ASSESSMENT');
console.log('  Grade: ' + r.assessment.grade);
for (const note of r.assessment.notes) {
